(* [comment removed for export] *)
Lemma x4_le16_lor : forall b0 b1, 0 <= b0 < 256 -> 0 <= b1 < 256 ->
  Z.lor (bv_unsigned (Z_to_bv 8 b1) ≪ 8 mod 18446744073709551616) (bv_unsigned (Z_to_bv 8 b0)) = b0 + 256 * b1.
Proof.
  intros b0 b1 H0 H1.
  assert (E : forall b, 0 <= b < 256 -> bv_unsigned (Z_to_bv 8 b) = b).
  { intros b Hb. rewrite Z_to_bv_unsigned. unfold bv_wrap, bv_modulus. cbn. apply Z.mod_small. lia. }
  rewrite (E b1 H1), (E b0 H0).
  assert (S : Z.shiftl b1 8 = b1 * 256) by (rewrite Z.shiftl_mul_pow2 by lia; reflexivity).
  rewrite S, Z.mod_small by lia.
  rewrite Z.lor_comm, <- S. apply lor_shiftl8_add; lia.
Qed.

(* [comment removed for export] *)
Lemma x4_land_le : forall x m, 0 <= x -> 0 <= Z.land x m <= x.
Proof.
  intros x m Hx.
  assert (D : Z.land (Z.land x m) (Z.ldiff x m) = 0).
  { apply Z.bits_inj'; intros k Hk. rewrite Z.land_spec, Z.land_spec, Z.ldiff_spec, Z.bits_0.
    destruct (Z.testbit x k), (Z.testbit m k); reflexivity. }
  assert (X : Z.lxor (Z.land x m) (Z.ldiff x m) = x).
  { apply Z.bits_inj'; intros k Hk. rewrite Z.lxor_spec, Z.land_spec, Z.ldiff_spec.
    destruct (Z.testbit x k), (Z.testbit m k); reflexivity. }
  rewrite <- (Z.add_nocarry_lxor _ _ D) in X.
  assert (0 <= Z.ldiff x m) by (rewrite Z.ldiff_land; apply Z.land_nonneg; left; exact Hx).
  assert (0 <= Z.land x m) by (apply Z.land_nonneg; left; exact Hx).
  lia.
Qed.

(* [comment removed for export] *)
Lemma x4_ids_ok : forall bs d, Forall (fun c => 0 <= c < 256) bs -> init_dstream bs = Ok d ->
  0 <= bd_cont d < 2^64 /\ 0 <= bd_bits d <= 64 /\ 1 <= zlen bs /\ 0 <= bd_ptr d /\
  (bd_ptr d = 0 \/ bd_ptr d + 8 <= zlen bs) /\ (8 <= bd_ptr d -> bd_bits d <= 8).
Proof.
  intros bs d BY E.
  destruct (init_dstream_ok bs (Forall_all_bytes bs BY)) as [[e E2] | [d2 (E2 & OK & _ & SH)]].
  - rewrite E in E2. discriminate.
  - rewrite E in E2. injection E2 as E3. subst d2.
    unfold bitD_ok in OK. unfold FseNCount.Zlength in OK, SH. lia.
Qed.

(* [comment removed for export] *)
Lemma x4_m1 : Z_to_bv 64 (-1) = Z_to_bv 64 (2^64 - 1).
Proof. apply bv_eq. vm_compute. reflexivity. Qed.

(* [comment removed for export] *)
Lemma x4_zx16 : forall c, 0 <= c < 2^16 -> zx16 (Z_to_bv 64 c) = Z_to_bv 64 c.
Proof. intros c Hc. unfold zx16. rewrite unsigned_lit by lia. rewrite Z.mod_small by lia. reflexivity. Qed.

(* [comment removed for export] *)
Lemma x4_uzx16 : forall c, 0 <= c < 2^16 -> bv_unsigned (zx16 (Z_to_bv 64 c)) = c.
Proof. intros c Hc. rewrite x4_zx16 by exact Hc. apply unsigned_lit. lia. Qed.
